      使用千牛承接售前咨询、物流查询与售后问题登记，每月处理约800次咨询按流程处理售后：登记问题后，退款提交主管审批，复杂投诉转交主管跟进










  技能证书




    办公软件：Excel其他：千牛


















(() => {
          window.addEventListener('load', () => {
            let timer;
            const fonts = document.fonts ? document.fonts.ready : Promise.resolve();
            Promise.race([fonts, new Promise(resolve => { timer = setTimeout(resolve, 300); })])
              .catch(() => {}).then(() => {
                clearTimeout(timer);
                parent.postMessage({type: 'huhua-preview-loaded', token: 2,
                  height: Math.ceil(Math.max(1123, document.body.getBoundingClientRect().height))}, '*');
              });
          }, {once: true});
        })();



